function controllerDiagram(type){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 420 180');svg.setAttribute('role','img');svg.setAttribute('aria-label','Controller panel illustration');const node=(name,attrs)=>{const n=document.createElementNS(svg.namespaceURI,name);for(const [k,v]of Object.entries(attrs))n.setAttribute(k,v);svg.append(n);};node('rect',{x:15,y:10,width:390,height:160,rx:14,fill:type==='dak'?'#bbbdb2':'#d3d8d1',stroke:'#8a9589','stroke-width':3});const lcdX=type==='vision'?265:30;node('rect',{x:lcdX,y:30,width:type==='dak'?160:120,height:28,rx:3,fill:'#bed092',stroke:'#445442','stroke-width':5});const groups=type==='vision'?[[30,30,2,5],[120,30,2,5],[265,76,4,4]]:type==='2000'?[[30,76,4,4],[164,30,2,6],[265,30,2,6]]:[[30,76,6,4],[220,76,3,4],[315,76,2,4]];for(const [x,y,cols,rows]of groups)for(let row=0;row<rows;row++)for(let col=0;col<cols;col++)node('rect',{x:x+col*28,y:y+row*20,width:23,height:15,rx:2,fill:col%2?'#e6c986':'#e8ece3',stroke:'#8b968b'});return svg;}
const library=document.getElementById('controller-library');
if(library){for(const c of rinkControllers){const card=document.createElement('a');card.className='controller-card';card.href=c.url;const visual=document.createElement('div');visual.className='controller-card-visual';if(c.photo){const img=document.createElement('img');img.src=c.photo;img.alt=c.name+' · '+(c.kind||'reference photograph');img.loading='lazy';visual.append(img);}else visual.append(controllerDiagram(c.diagram));const meta=document.createElement('div');meta.className='controller-card-copy';const brand=document.createElement('small');brand.textContent=c.family.toUpperCase();const title=document.createElement('h2');title.textContent=c.name;const p=document.createElement('p');p.textContent=c.note;const kind=document.createElement('small');kind.textContent=c.kind||'Controller reference photograph';kind.className='reference-kind';meta.append(kind);const link=document.createElement('span');link.textContent='Practise this controller ↗';meta.append(brand,title,p,link);card.append(visual,meta);card.dataset.family=c.family;card.dataset.search=[c.name,c.short,c.note,c.family].join(' ').toLowerCase();library.append(card);}}
const nav=document.querySelector('.controller-switch');
if(nav){const path=location.pathname.split('/').pop().replace(/\.html$/,'')||'index';const selected=rinkControllers.find(c=>c.url.replace('.html','')===path)||rinkControllers[0];nav.replaceChildren();const label=document.createElement('label');label.textContent='YOUR CONTROLLER';const select=document.createElement('select');select.setAttribute('aria-label','Switch controller');for(const c of rinkControllers){const option=document.createElement('option');option.value=c.url;option.textContent=c.short;option.selected=c.id===selected.id;select.append(option);}label.append(select);select.onchange=()=>{location.href=select.value;};const libraryLink=document.createElement('a');libraryLink.href='controllers.html';libraryLink.textContent='▦ Find your controller';libraryLink.className='library-link';const selectedLink=document.createElement('a');selectedLink.href=selected.url;selectedLink.setAttribute('aria-current','page');selectedLink.textContent=selected.short;selectedLink.className='current-controller';nav.append(label,libraryLink,selectedLink);const brand=document.querySelector('.brand');if(brand)brand.href='./';}
for(const link of document.querySelectorAll('a[href="#controller-reference"]'))link.addEventListener('click',()=>{document.getElementById('controller-reference').open=true;});

// The identification library remains searchable without changing simulator URLs.
if(library){const search=document.getElementById('controller-search'),family=document.getElementById('controller-family'),count=document.getElementById('library-count');if(search&&family){for(const name of [...new Set(rinkControllers.map(c=>c.family))].sort()){const o=document.createElement('option');o.value=name;o.textContent=name;family.append(o);}const filter=()=>{let visible=0;for(const card of library.children){const show=(!family.value||card.dataset.family===family.value)&&card.dataset.search.includes(search.value.trim().toLowerCase());card.hidden=!show;if(show)visible++;}count.textContent=visible+' of '+rinkControllers.length+' playable controller profiles'+(visible?'':' · Try another model or manufacturer');};search.oninput=filter;family.onchange=filter;filter();}}
